            out=subprocess.check_output(['pdftotext','-f','1','-l','2',path,'-'], stderr=subprocess.DEVNULL)
            return out.decode('utf-8','ignore')
        except Exception:
            return ''
    elif ext=='.docx':
        try:
            with zipfile.ZipFile(path) as z:
                xml=z.read('word/document.xml').decode('utf-8','ignore')
            return re.sub('<[^<]+?>',' ',xml)
        except Exception:
            return ''
    elif ext=='.pptx':
        try:
            with zipfile.ZipFile(path) as z:
                texts=[]
                for slide in sorted([f for f in z.namelist() if f.startswith('ppt/slides/slide') and f.endswith('.xml')]):
                    xml=z.read(slide).decode('utf-8','ignore')
                    texts.append(re.sub('<[^<]+?>',' ',xml))
            return ' '.join(texts)
        except Exception:
            return ''
    return ''

assignments={}
for f in files:
    if f in overrides:
        assignments[f]=overrides[f]
        continue
    path=os.path.join(base,f)
    text=extract_text(path)
    scores={cat:0 for cat in cats}
    for cat, regs in cat_regex.items():
        for r in regs:
            scores[cat]+=len(r.findall(text))
    best=max(scores, key=lambda k: scores[k])
    assignments[f]=best

# Move files
for f,cat in assignments.items():
    src=os.path.join(base,f)
    dest=os.path.join('papers',cat,f)
    shutil.move(src,dest)

# Print summary counts
